function nodeGraphTSeriesValueDisplayModes() {
  return [
    {
      key: "value",
      label: "Value Line",
      renderer: "value",
      settingsSchema: "value",
      // Combined Digital/Analog openness (not In × gate on out "0").
      source: { value: "Open" } },
  ];
}

/** t2…t11 / 2t…11t face: per-path gain cells + crossfade playhead. */
function nodeGraphTSeriesCrossfadeDisplayModes() {
  return [
    {
      key: "crossfade",
      label: "Crossfade",
      renderer: "tSeriesFace",
      settingsSchema: "",
      source: { value: "Open" } },
  ];
}

function nodeGraphTSeriesCrossfadeVisualInputs() {
  return [
    { key: "tSeriesAnalog", label: "A", port: "Analog" },
    { key: "tSeriesDigital", label: "D", port: "Digital" },
  ];
}

function nodeGraphTSeriesModuleDefinition(lastIndex) {
  const last = Math.max(0, Math.min(10, Math.round(nodeGraphFiniteNumber(lastIndex))));
  return {
    planRole: "processor",
    chrome: NodeGraphModuleChromeLayout.LayoutA,
    // Crossfade face: one cell per numbered path, fill = gain, playhead = position.
    displayType: "tSeriesFace",
    displayHeightGu: 1,
    displayModes: nodeGraphTSeriesCrossfadeDisplayModes(),
    // A/D input rings (summed cables, every engine sample) drive the face.
    visualSink: true,
    visualInputs: nodeGraphTSeriesCrossfadeVisualInputs(),
    digitalInputs: ["Digital"],
    inputAliases: { A: "Analog", D: "Digital", Mono: "In" },
    inputLabels: { Analog: "A", Digital: "D", In: "→" },
    inputs: ["In", "Analog", "Digital"],
    outputs: Array.from({ length: last + 1 }, (_, index) => String(index)),
    parameters: [],
    defaultWidthGu: last >= 10 ? 5 : last >= 1 ? 4 : 3,
    defaultHeightGu: last >= 8 ? 7 : last >= 6 ? 6 : last >= 4 ? 5 : last >= 2 ? 4 : 3,
    defaultUi: {
      buttonsHidden: true,
      titleHidden: false } };
}

/** Nt mux: inputs 0…(N-1) + A/D → Out. Mirror of tN demux. Name digit = path count. */
function nodeGraphTSeriesMuxModuleDefinition(lastIndex) {
  const last = Math.max(1, Math.min(10, Math.round(nodeGraphFiniteNumber(lastIndex))));
  const numbered = Array.from({ length: last + 1 }, (_, index) => String(index));
  return {
    planRole: "processor",
    chrome: NodeGraphModuleChromeLayout.LayoutA,
    // Crossfade face: one cell per numbered path, fill = gain, playhead = position.
    displayType: "tSeriesFace",
    displayHeightGu: 1,
    displayModes: nodeGraphTSeriesCrossfadeDisplayModes(),
    // A/D input rings (summed cables, every engine sample) drive the face.
    visualSink: true,
    visualInputs: nodeGraphTSeriesCrossfadeVisualInputs(),
    digitalInputs: ["Digital"],
    inputAliases: { A: "Analog", D: "Digital" },
    inputLabels: { Analog: "A", Digital: "D" },
    inputs: [...numbered, "Analog", "Digital"],
    outputAliases: { Mono: "Out" },
    outputLabels: { Out: "←" },
    outputs: ["Out"],
    parameters: [],
    defaultWidthGu: last >= 10 ? 5 : last >= 6 ? 4 : 3,
    defaultHeightGu: last >= 8 ? 8 : last >= 5 ? 7 : last >= 3 ? 6 : 5,
    defaultUi: {
      buttonsHidden: true,
      titleHidden: false } };
}

/** Lone `t` — LayoutB with arrow In/Out so the side bands stay one glyph wide. */
function nodeGraphTSeriesSingleModuleDefinition() {
  return {
    planRole: "processor",
    chrome: NodeGraphModuleChromeLayout.LayoutB,
    layoutBPortLabels: true,
    // Torch face: 4 frames crossfaded by Open (0..1) from the A/D input rings.
    displayType: "torchFace",
    visualSink: true,
    visualInputs: nodeGraphTSeriesCrossfadeVisualInputs(),
    // Sample-exact A/D rings (like LED Dot In): Open is averaged per drawn frame.
    bufferedInputs: ["Analog", "Digital"],
    displayHeightGu: 1,
    displayModes: [
      {
        key: "torch",
        label: "Torch",
        renderer: "torchFace",
        settingsSchema: "torchFace",
        source: { value: "Open" } },
    ],
    digitalInputs: ["Digital"],
    inputAliases: { A: "Analog", D: "Digital", Mono: "In" },
    inputLabels: { Analog: "A", Digital: "D", In: "→" },
    inputs: ["In", "Analog", "Digital"],
    outputAliases: { Out: "0" },
    outputLabels: { 0: "←" },
    outputs: ["0"],
    parameters: [],
    defaultWidthGu: 3,
    defaultUi: {
      buttonsHidden: true,
      titleHidden: false } };
}

