// Music Player playback-rate parameter. Speed and << >> share this one
// definition; << >> only changes key, label, range, default and tooltip. The
// engine plays at (Speed + Speed CV) + << >>.
function nodeGraphPlaybackSpeedParameter(overrides = {}) {
  return {
    defaultValue: "1",
    key: "speed",
    label: "Speed",
    linearSmoothing: false,
    max: "8",
    maxDigits: 4,
    mid: "1",
    min: "0",
    step: "any",
    unit: "x",
    ...overrides,
  };
}

function nodeGraphControllerBiasParameter() {
  return {
    bipolar: false,
    defaultValue: "0",
    parameterOutput: false,
    key: "offset",
    label: "Bias",
    max: "1",
    mid: "0.5",
    min: "0",
    nonlinearSlider: false,
    step: "any",
    linearSmoothing: true,
    smoothingMode: "internal",
    smoothingSeconds: 0.0333,
    smoothingType: "linear",
    tooltip: "Bias. The face edits this. Min, max, reverse, curve, and smooth time are Parameter Settings." };
}

function nodeGraphControllerDisplayParameter() {
  return [
    {
      choices: ["Mouse", "Smoothed"],
      defaultValue: "0",
      displayChoices: true,
      divideChoicesVisibly: true,
      key: "displaySource",
      label: "Display",
      linearSmoothing: false,
      max: "1",
      mid: "0",
      min: "0",
      step: "1",
      tooltip: "Mouse = pointer target. Smoothed = Bias after Parameter Settings smooth.",
      hidden: true },
  ];
}

function nodeGraphControllerModuleParameters() {
  return [
    nodeGraphControllerBiasParameter(),
    ...nodeGraphControllerDisplayParameter(),
  ];
}

function nodeGraphControllerButtonBiasParameter() {
  return {
    ...nodeGraphControllerBiasParameter(),
    step: "1",
    displayChoices: true,
    divideChoicesVisibly: true,
    choices: ["Off", "On"],
    tooltip: "Bias. Off/On choices by default. Min, max, reverse, curve, and smooth time are Parameter Settings." };
}

// Toggle / Momentary spawn with Bias smoothing Off (a press is a step; a
// smoothed ramp makes Trigger inlets strike at the first tiny sample). Spawn
// only: stamped into paramMeta by createNodeGraphPatchNode, so the user can
// turn it back on in Parameter Settings and saved patches keep their own meta.
const NODE_GRAPH_CONTROLLER_BUTTON_SPAWN_PARAM_META = Object.freeze({
  offset: Object.freeze({
    linearSmoothing: false,
    smoothingMode: "off",
    smoothingSeconds: 0,
    smoothingType: "linear",  // Off as app-wide: type stays Linear so turning the mode back on ramps
  }),
});

function nodeGraphControllerButtonModuleParameters() {
  return [
    nodeGraphControllerButtonBiasParameter(),
    ...nodeGraphControllerDisplayParameter(),
  ];
}

